package mcpserver

import (
	"github.com/google/jsonschema-go/jsonschema"
	"github.com/stufently/s3-mcp-ai-cli-kit/config"
	"github.com/stufently/s3-mcp-ai-cli-kit/provider"
	"strings"
)

type ToolSpec struct {
	Name, Levels, Capability, Fields, Required, Description string
	FileRoot                                                bool
}

var registry = []ToolSpec{
	{Name: "s3_list_buckets", Fields: "max_keys continuation_token", Description: "List the buckets these credentials can see, filtered by the configured bucket scope; read-only, up to 1000 per page. Use it to discover bucket names; to list keys inside a bucket use s3_list_objects. Returns buckets[] (name, created_at) and continuation_token, which is empty on the last page. Buckets outside the allowed scope are omitted rather than reported as errors."},
	{Name: "s3_list_objects", Fields: "bucket prefix max_keys continuation_token", Required: "bucket", Description: "List one page of current object keys under a prefix in a bucket; read-only. Use it to browse objects; use s3_list_object_versions for old versions and delete markers, and s3_largest_objects or s3_prefix_usage for size analysis across many pages. Returns objects[] (key, size in bytes, etag, last_modified, storage_class), truncated, and continuation_token for the next page. Fails with scope_denied outside the configured bucket/prefix scope."},
	{Name: "s3_head_object", Fields: "bucket key version_id", Required: "bucket key", Description: "Read one object's metadata without downloading its body; read-only. Use it to check existence, size or content type before s3_get_object, s3_download_file or s3_presign_get. Returns key, size (bytes), etag, content_type, last_modified, version_id and user metadata. A missing key fails with a not-found error (NotFound or http_404)."},
	{Name: "s3_get_object", Fields: "bucket key version_id max_bytes encoding", Required: "bucket key", Description: "Return a small object's whole body inline as UTF-8 text or base64; read-only. Use it for objects up to 262144 bytes (256 KiB); to look at the start of a larger file use s3_preview_object, to save it to disk use s3_download_file, and to hand it over use s3_presign_get. Returns key, bytes, data, encoding and content_type. Fails instead of truncating when the object exceeds max_bytes, and fails on non-UTF-8 content unless encoding is base64."},
	{Name: "s3_preview_object", Fields: "bucket key version_id max_bytes encoding", Required: "bucket key", Description: "Read only the first bytes of an object (default and maximum 65536) with a ranged GET; read-only. Use it to inspect the format or header of a file of any size; use s3_get_object when you need the full body of a small object. Returns key, bytes, data, encoding (base64 is chosen automatically for binary data when encoding is omitted), content_type, detected_type (sniffed MIME type) and, for .csv keys or CSV content types, csv_header."},
	{Name: "s3_presign_get", Capability: "presign", Fields: "bucket key version_id expires_seconds", Required: "bucket key", Description: "Create a time-limited signed HTTPS GET URL for one object; read-only, signs locally and does not check that the key exists. Use it to hand a large object to a human or another program instead of reading bytes through s3_get_object. Returns url, method, headers and expires_seconds (default 3600). Anyone holding the URL can download the object until it expires, so share it only with the intended recipient."},
	{Name: "s3_list_object_versions", Capability: "versioning", Fields: "bucket prefix max_keys continuation_token version_marker", Required: "bucket", Description: "List object versions and delete markers under a prefix; read-only, one page of up to 1000 entries. Use it to find a version_id to inspect or restore with s3_head_object, s3_get_object or s3_download_file; use s3_list_objects when only current objects matter. Returns versions[], delete_markers[], truncated, continuation_token and version_marker; send both markers back together for the next page."},
	{Name: "s3_list_multipart_uploads", Capability: "multipart", Fields: "bucket prefix max_keys continuation_token upload_id", Required: "bucket", Description: "List in-progress multipart uploads (started, not yet completed or aborted) in a bucket; read-only, one page of up to 1000. Use it for a raw page of uploads; use s3_unfinished_uploads to find uploads older than N hours across many pages, and s3_list_parts for the parts of one upload. Returns uploads[] (Key, UploadId, Initiated and more), truncated, continuation_token and upload_id_marker; send them back as continuation_token and upload_id for the next page."},
	{Name: "s3_list_parts", Capability: "multipart", Fields: "bucket key upload_id max_keys continuation_token", Required: "bucket key upload_id", Description: "List the parts already uploaded for one multipart upload; read-only. Use it before s3_multipart_complete to collect part numbers and ETags, or to check upload progress. Returns parts[] (PartNumber, ETag, Size, LastModified), truncated and continuation_token (a part-number marker) for the next page. An unknown upload_id fails with NoSuchUpload."},
	{Name: "s3_get_bucket_config", Capability: "bucket_config", Fields: "bucket", Required: "bucket", Description: "Read a bucket's configuration in one call: location, versioning status, CORS rules, bucket policy JSON and Object Lock configuration; read-only. Use it before changing any of them with the s3_put_bucket_* tools. Each section holds its value (versioning status is empty when versioning was never enabled), {\"status\":\"absent\"} when nothing is configured, or {\"status\":\"unsupported\"} when the provider lacks the feature. Needs whole-bucket scope: fails with scope_denied when only some prefixes of the bucket are allowed."},
	{Name: "s3_largest_objects", Fields: "bucket prefix max_scan limit continuation_token", Required: "bucket", Description: "Find the largest objects under a prefix by scanning up to max_scan keys (default 10000); read-only. Use it to locate what consumes space; use s3_prefix_usage for totals per sub-prefix and s3_list_objects for plain browsing. Returns objects[] sorted by size descending (at most limit, default 10), scanned, partial and continuation_token. partial:true means the scan stopped early and the ranking covers only scanned keys; pass continuation_token to rank the next batch."},
	{Name: "s3_prefix_usage", Fields: "bucket prefix max_scan continuation_token result_offset", Required: "bucket", Description: "Sum bytes and object counts per first-level sub-prefix under prefix, scanning up to max_scan keys (default 10000); read-only. Use it to see which folders take space; use s3_largest_objects for individual files. Returns prefixes[] (prefix, bytes, count; objects directly under prefix are grouped under prefix itself), scanned, partial, continuation_token and next_result_offset when more than 1000 rows exist. partial:true means totals cover only the scanned keys; this is an estimate, not billing data."},
	{Name: "s3_unfinished_uploads", Capability: "multipart", Fields: "bucket prefix max_scan older_than_hours continuation_token upload_id", Required: "bucket", Description: "Find multipart uploads started more than older_than_hours ago (default 24), scanning up to max_scan uploads (default 10000); read-only. Use it to spot abandoned uploads that still occupy storage, then remove them with s3_multipart_abort; use s3_list_multipart_uploads for a raw page regardless of age. Returns uploads[] (key, upload_id, initiated; at most 1000), scanned, partial, continuation_token and upload_id_marker; when partial is true send both markers back to continue."},
	{Name: "s3_get_object_tagging", Capability: "object_tagging", Fields: "bucket key version_id", Required: "bucket key", Description: "Read the tag set of one object or of a specific version; read-only. Use it before s3_put_object_tagging, which replaces the whole set. Returns tags[] as Key/Value pairs; an object without tags returns an empty list."},
	{Name: "s3_download_file", FileRoot: true, Fields: "bucket key version_id path overwrite confirm", Required: "bucket key path", Description: "Stream one object into a local file under the configured file root without passing bytes through the model; no size limit. Use it for objects too large for s3_get_object; use s3_presign_get when a human needs the file instead. Writes through a temporary file and publishes it atomically. By default refuses an existing destination, including one created during the download; overwrite:true replaces it after destructive approval. Returns the written path."},
	{Name: "s3_put_object", Levels: "write", Fields: "bucket key data encoding content_type max_bytes overwrite confirm", Required: "bucket key data", Description: "Create or replace a small object from inline data, at most 262144 bytes after base64 decoding. Use it for small text, JSON or config files; use s3_upload_file for local files and s3_presign_put or s3_multipart_create for large data. By default refuses an existing key with already_exists, and fails on providers without conditional writes unless overwrite is true; overwrite:true replaces the object and requires destructive approval. Returns etag and version_id."},
	{Name: "s3_create_folder", Levels: "write", Fields: "bucket key", Required: "bucket key", Description: "Create an empty folder marker: a zero-byte object whose key ends in \"/\" (added when missing). Use it so an empty prefix shows up in consoles and listings; uploading keys under a prefix does not need it. Never overwrites: fails with already_exists when the marker exists, and fails on providers without conditional writes. Returns etag and version_id."},
	{Name: "s3_copy_object", Levels: "write", Fields: "bucket key source_bucket source_key overwrite confirm", Required: "bucket key source_bucket source_key", Description: "Copy an object server-side from source_bucket/source_key to bucket/key; bytes do not pass through the model and the source is kept. Use it to duplicate an object; use s3_move_object to also delete the source. Source and destination must both be inside the configured scope and must differ. By default refuses an existing destination; overwrite:true (also needed on providers without conditional writes) replaces it and requires destructive approval. Returns result (ETag, LastModified) and version_id."},
	{Name: "s3_presign_put", Capability: "presign", Levels: "write", Fields: "bucket key expires_seconds content_type confirm", Required: "bucket key", Description: "Create a time-limited signed HTTPS PUT URL so a human or another program can upload one object directly, bypassing the model. Use it for single uploads too big for s3_put_object; for very large files use s3_multipart_create with s3_multipart_presign_part. Always requires destructive approval because the URL can overwrite the key without any existence check. Returns url, method, headers to send with the PUT (including Content-Type when set) and expires_seconds (default 3600)."},
	{Name: "s3_multipart_create", Levels: "write", Capability: "multipart", Fields: "bucket key content_type", Required: "bucket key", Description: "Start a multipart upload for bucket/key and return its upload_id. Use it for objects too large for one PUT: sign each part with s3_multipart_presign_part, upload the parts outside the model, then finish with s3_multipart_complete or cancel with s3_multipart_abort. For a local file under the file root, s3_upload_file does all steps in one call. Nothing appears at key until completion, but uploaded parts occupy storage until the upload is completed or aborted."},
	{Name: "s3_multipart_presign_part", Levels: "write", Capability: "multipart presign", Fields: "bucket key upload_id part_number expires_seconds", Required: "bucket key upload_id part_number", Description: "Create a signed HTTPS PUT URL for one part of an upload started with s3_multipart_create; signs locally without an S3 request. Upload the part bytes to the URL outside the model and keep the ETag response header for s3_multipart_complete. S3 requires every part except the last to be at least 5 MiB. Returns url, method and headers; the URL lives expires_seconds (default 3600)."},
	{Name: "s3_multipart_complete", Levels: "write", Capability: "multipart", Fields: "bucket key upload_id parts overwrite confirm", Required: "bucket key upload_id parts", Description: "Finish a multipart upload by assembling the listed parts into the object at bucket/key. Use it after every part is uploaded; s3_list_parts shows what has arrived. parts must be in ascending part_number order with the ETag returned by each part upload. By default checks the destination first and refuses to replace an existing object; overwrite:true (also needed on providers without conditional writes) replaces it and requires destructive approval. Returns etag and version_id; the upload_id cannot be reused."},
	{Name: "s3_put_object_tagging", Levels: "write", Capability: "object_tagging", Fields: "bucket key version_id tags", Required: "bucket key tags", Description: "Replace the entire tag set of one object or of a specific version. Read the current tags with s3_get_object_tagging first and include the ones to keep: tags missing from the map are removed, and {} clears all tags. Does not change the object body and needs no approval. Returns updated:true on success."},
	{Name: "s3_upload_file", Levels: "write", Capability: "multipart", FileRoot: true, Fields: "bucket key path part_size content_type overwrite confirm", Required: "bucket key path", Description: "Upload a local file from under the configured file root to bucket/key with a managed multipart upload; bytes do not pass through the model and there is no inline size limit. Use it for local files of any size; use s3_put_object for small inline data. By default refuses an existing key; overwrite:true (also needed on providers without conditional writes) replaces it and requires destructive approval. Returns etag, version_id and upload_id."},
	{Name: "s3_delete_object", Levels: "delete", Fields: "bucket key version_id confirm", Required: "bucket key", Description: "Delete one object, or one specific version when version_id is set. Always requires destructive approval. Without version_id, a bucket with versioning Enabled gets a delete marker and older versions stay recoverable, while an unversioned or Suspended bucket loses the current object for good; with version_id that version is removed permanently. Deleting a missing key succeeds. Use s3_delete_objects for up to 1000 keys at once. Returns delete_marker and version_id."},
	{Name: "s3_delete_objects", Levels: "delete", Fields: "bucket objects confirm", Required: "bucket objects", Description: "Delete 1-1000 objects, optionally specific versions, in one bucket with a single batch request. Always requires destructive approval, and every key is scope-checked before any request. Versioning works as in s3_delete_object: without version_id only a bucket with versioning Enabled keeps the data recoverable; with version_id removal is permanent. Returns deleted[] and errors[]; check errors, because some keys can fail while the call itself succeeds."},
	{Name: "s3_move_object", Levels: "write delete", Capability: "conditional_delete", Fields: "bucket key source_bucket source_key overwrite confirm", Required: "bucket key source_bucket source_key", Description: "Move an object: server-side copy from source_bucket/source_key to bucket/key, then delete the source. Always requires destructive approval. The source is deleted only if its ETag is unchanged since the copy; if it changed or deletion fails, the copy is kept and the error says so. By default refuses an existing destination; overwrite:true (also needed on providers without conditional writes) replaces it. Use s3_copy_object to keep the source. Returns result and version_id of the new copy."},
	{Name: "s3_multipart_abort", Levels: "delete", Capability: "multipart", Fields: "bucket key upload_id confirm", Required: "bucket key upload_id", Description: "Abort an unfinished multipart upload and delete every part uploaded so far, freeing their storage. Use it on stale uploads found by s3_unfinished_uploads or s3_list_multipart_uploads. Always requires destructive approval; the upload_id cannot be resumed afterwards. An already completed object at key is not touched. Returns aborted:true."},
	{Name: "s3_create_bucket", Levels: "admin", Capability: "bucket_create", Fields: "bucket object_lock", Required: "bucket", Description: "Create a new bucket in the configured pool (region). Use it only for a bucket that does not exist yet; a taken name fails with BucketAlreadyExists or BucketAlreadyOwnedByYou. Storage class and tariff are chosen in the provider console, not through this tool. object_lock:true enables Object Lock, which in S3 also enables versioning and cannot be turned off later. Returns location."},
	{Name: "s3_delete_bucket", Levels: "admin delete", Capability: "bucket_delete", Fields: "bucket confirm", Required: "bucket", Description: "Delete an empty bucket. Always requires destructive approval and whole-bucket scope. Fails with BucketNotEmpty while any object, version or delete marker remains: empty it first with s3_delete_objects, using s3_list_object_versions for versioned buckets. Returns deleted:true."},
	{Name: "s3_put_bucket_versioning", Levels: "admin", Capability: "versioning", Fields: "bucket status confirm", Required: "bucket status", Description: "Turn bucket versioning on (Enabled) or pause it (Suspended). Enabled keeps every overwritten or deleted object as a recoverable version, which consumes storage; Suspended stops creating new versions but keeps existing ones, and requires destructive approval. In S3 versioning cannot be fully disabled once enabled. Check the current state with s3_get_bucket_config. Returns status."},
	{Name: "s3_put_bucket_cors", Levels: "admin", Capability: "cors", Fields: "bucket cors_rules", Required: "bucket cors_rules", Description: "Replace the bucket's whole CORS configuration (browser cross-origin access) with cors_rules. Existing rules are discarded, so read them first with s3_get_bucket_config and include the ones to keep. Needs no approval. Returns updated:true."},
	{Name: "s3_put_bucket_policy", Levels: "admin", Capability: "bucket_policy", Fields: "bucket policy confirm", Required: "bucket policy", Description: "Replace the bucket policy with a new JSON policy document. A wrong policy can make the bucket public or lock everyone out, so this always requires destructive approval; read the current policy with s3_get_bucket_config first. Use s3_delete_bucket_policy to remove the policy entirely. Returns updated:true."},
	{Name: "s3_delete_bucket_policy", Levels: "admin", Capability: "bucket_policy", Fields: "bucket confirm", Required: "bucket", Description: "Remove the bucket policy entirely, so access falls back to account and key permissions. Always requires destructive approval; read the current policy with s3_get_bucket_config first if you may need to restore it. Use s3_put_bucket_policy to change rather than remove it. Returns deleted:true."},
	{Name: "s3_put_object_lock_configuration", Levels: "admin", Capability: "object_lock_config", Fields: "bucket lock_configuration confirm", Required: "bucket lock_configuration", Description: "Set the bucket's default Object Lock retention (mode GOVERNANCE or COMPLIANCE, in days or years). Object Lock must already be enabled on the bucket. Always requires destructive approval: COMPLIANCE retention cannot be shortened or removed, and locked versions cannot be deleted until it expires. Check the current setting with s3_get_bucket_config. Returns updated:true."},
}

func enabled(spec ToolSpec, p provider.Profile, c config.Config) bool {
	for _, level := range strings.Fields(spec.Levels) {
		if !c.Allow[level] {
			return false
		}
	}
	for _, capability := range strings.Fields(spec.Capability) {
		if !p.Supports(capability) {
			return false
		}
	}
	return !spec.FileRoot || c.FileRoot != ""
}
func Tools(p provider.Profile, c config.Config) []ToolSpec {
	out := []ToolSpec{}
	for _, spec := range registry {
		if enabled(spec, p, c) {
			out = append(out, spec)
		}
	}
	return out
}
func inputSchema(spec ToolSpec) *jsonschema.Schema {
	props := map[string]*jsonschema.Schema{}
	for _, field := range strings.Fields(spec.Fields) {
		s := &jsonschema.Schema{Type: "string", Description: paramDescription(spec.Name, field)}
		switch field {
		case "overwrite", "confirm", "object_lock":
			s.Type = "boolean"
		case "max_keys", "max_bytes", "expires_seconds", "max_scan", "limit", "part_number", "part_size", "result_offset":
			s.Type = "integer"
			s.Minimum = new(float64)
		case "older_than_hours":
			s.Type = "number"
			s.Minimum = new(float64)
		case "objects", "parts", "cors_rules":
			s.Type = "array"
			s.Items = &jsonschema.Schema{Type: "object"}
		case "tags", "lock_configuration":
			s.Type = "object"
		}
		props[field] = s
	}
	return &jsonschema.Schema{Type: "object", Properties: props, Required: strings.Fields(spec.Required), AdditionalProperties: &jsonschema.Schema{Not: &jsonschema.Schema{}}}
}
